/* Njia — regenerate icons/og-image.jpg, the link-share card.
 *
 * WHY THIS EXISTS.
 *
 * Every other raster in this repository is generated by a script and guarded
 * against going stale. og-image.jpg was the exception: made once by hand,
 * committed, and never rebuilt. So when the brand mark was redrawn from a
 * shield to the leaf the sheets actually specify, this file kept the shield —
 * and it is the single most visible surface Njia has. It is what appears in
 * WhatsApp when a school-leaver forwards the link to a friend, which is the
 * app's main distribution channel. The icons had a generator and a staleness
 * test and were correct within minutes; the share card had neither and was
 * wrong until someone happened to open it.
 *
 * Hand-made assets do not stay in step with the thing they depict. That is not
 * a discipline problem, it is a missing build step, so here is the build step.
 *
 * WHY IT IS SEPARATE FROM tools/build-brand-assets.mjs.
 *
 * That script writes to brand/ — deliverables for social profiles and decks,
 * which the app never loads. This one writes to icons/, because the share card
 * IS a runtime asset: index.html points og:image and twitter:image straight at
 * it. Different destination, different rules, different script.
 *
 * NOT to be confused with brand/social-banner-16x9.png. The banner is a
 * PROFILE header and can be calm. This card has one job — earn a click from
 * someone scrolling a WhatsApp group — so it leads with the promise rather
 * than the logo.
 *
 * RUN:  node tools/build-og-image.mjs
 *       NODE_PATH=/path/to/node_modules node tools/build-og-image.mjs
 */
import { createRequire } from 'node:module';
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const require = createRequire(path.join(root, '/'));

let chromium;
for (const p of [process.env.NODE_PATH, '/usr/lib/node_modules', '/usr/local/lib/node_modules']) {
  if (!p) continue;
  for (const dir of p.split(':')) {
    try { ({ chromium } = require(path.join(dir, 'playwright/index.js'))); break; } catch { /* keep looking */ }
  }
  if (chromium) break;
}
if (!chromium) {
  try { ({ chromium } = require('playwright')); } catch {
    console.error('Playwright not resolvable. Supply it out-of-tree, e.g.\n'
      + '  NODE_PATH=/tmp/njia/node_modules node tools/build-og-image.mjs');
    process.exit(2);
  }
}

const css = fs.readFileSync(path.join(root, 'css', 'styles.css'), 'utf8');
const mark = fs.readFileSync(path.join(root, 'icons', 'logo-mark.svg'), 'utf8');

/* Read from the live stylesheet rather than restated, so a palette or type
 * change in the app reaches this card on the next run instead of leaving it
 * quietly off-brand — the failure this whole file exists to end. */
const grab = (name) => {
  const at = css.indexOf(':root {');
  const slice = css.slice(at, css.indexOf('\n}', at));
  const m = slice.match(new RegExp(`${name}:\\s*([^;]+);`));
  if (!m) throw new Error(`${name} not found in :root — the stylesheet moved`);
  return m[1].trim();
};
const SERIF = grab('--serif');
const CREAM = grab('--bg');
const BROWN = grab('--ink');
const GOLD = grab('--accent');
const TERRACOTTA = grab('--primary');

const SITE_ORIGIN = 'https://njiacareerpathways.work';
const W = 1200, H = 630;

/* The headline is the site's own, split at the same point the hero splits it.
 * Kept here as one string rather than scraped from index.html: the hero markup
 * carries spans and entities, and a card that silently changed wording because
 * a class name moved would be worse than one that is stated. */
const HEAD_A = "Career clarity shouldn't";
const HEAD_B = 'cost ';
const HEAD_C = 'what consultants charge.';
const SUB = 'A free, evidence-based career diagnostic — matched against real Kenyan courses, fees and funding.';

const page = `<!doctype html><meta charset="utf-8">
<style>
  *{box-sizing:border-box;margin:0;padding:0}
  body{width:${W}px;height:${H}px;font-family:${SERIF};-webkit-font-smoothing:antialiased}
  #card{
    width:${W}px;height:${H}px;padding:60px 72px;
    display:flex;flex-direction:column;justify-content:space-between;
    background:${BROWN};
    background-image:radial-gradient(120% 100% at 88% 8%, ${TERRACOTTA}55 0%, transparent 58%),
                     linear-gradient(150deg, ${BROWN} 0%, #52280A 55%, ${BROWN} 100%);
  }
  .lockup{display:flex;align-items:center;gap:20px}
  .lockup .mark{width:58px}
  .lockup .mark svg{display:block;width:100%;height:auto}
  .word{font-family:${SERIF};font-weight:700;font-size:44px;color:${CREAM};line-height:1}
  .tag{font-family:system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;font-weight:700;
       font-size:15px;letter-spacing:.13em;text-transform:uppercase;color:${GOLD};margin-top:7px}
  h1{font-family:${SERIF};font-weight:700;font-size:74px;line-height:1.08;color:${CREAM};max-width:15.5em}
  h1 em{font-style:normal;color:${GOLD}}
  p{font-family:system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;font-size:25px;line-height:1.45;
    color:rgba(245,233,212,.86);max-width:26em;margin-top:26px}
</style>
<div id="card">
  <div class="lockup">
    <div class="mark">${mark}</div>
    <div>
      <div class="word">Njia</div>
      <div class="tag">Data-driven career pathway for Kenyan youth</div>
    </div>
  </div>
  <div>
    <h1>${HEAD_A}<br>${HEAD_B}<em>${HEAD_C}</em></h1>
    <p>${SUB}</p>
  </div>
</div>`;

const browser = await chromium.launch({
  executablePath: process.env.CHROMIUM_PATH || '/opt/pw-browsers/chromium'
});
/* Light scheme pinned. logo-mark.svg carries a prefers-color-scheme rule that
 * swaps the leaf outline to cream for dark browser chrome; inlined here it
 * would otherwise follow whatever scheme the build machine happens to be in,
 * and the outline would vanish against the card's dark ground on one machine
 * and not another. */
const ctx = await browser.newContext({
  viewport: { width: W, height: H }, deviceScaleFactor: 1, colorScheme: 'light'
});
const p = await ctx.newPage();
await p.setContent(page, { waitUntil: 'load' });
await p.waitForTimeout(300);

const out = path.join(root, 'icons', 'og-image.jpg');
/* JPEG at 88: the card is a photograph-like gradient, where JPEG beats PNG by
 * roughly 4x for no visible loss, and this file is fetched by every social
 * crawler that ever sees a shared link. */
await p.locator('#card').screenshot({ path: out, type: 'jpeg', quality: 88 });
await browser.close();

/* THE RE-SCRAPE STEP SHOULD NOT EXIST.
 *
 * Social platforms cache a share card against its URL, hard and for a long
 * time. So when the mark was redrawn and this card was rebuilt, every link
 * already circulating in WhatsApp kept showing the retired shield — and the
 * only fix on offer was "go and re-scrape the URL in the Facebook debugger",
 * a manual step a human has to remember, with no guard and no way to tell
 * whether it worked.
 *
 * A manual step that exists only because a URL never changes is a missing
 * build step, which is the same lesson this file already carries about the
 * card having no generator. So the URL now carries a short content hash of the
 * JPEG itself. Rebuild the card and the hash changes; the platforms see a URL
 * they have never fetched and fetch it. Rebuild with no visual change and the
 * hash is identical, so nothing is invalidated for nothing.
 *
 * The references live in index.html, and this script rewrites them rather than
 * asking anyone to keep two things in step by hand. build-static-pages.mjs
 * reads the versioned URL back out of index.html, so there is one source of
 * truth for it. tests/artefacts.test.js fails the build if the hash in the
 * markup stops matching the bytes on disk. */
const hash = crypto.createHash('sha256').update(fs.readFileSync(out)).digest('hex').slice(0, 10);
const versioned = `${SITE_ORIGIN}/icons/og-image.jpg?v=${hash}`;

const indexPath = path.join(root, 'index.html');
const before = fs.readFileSync(indexPath, 'utf8');
const after = before.replace(
  /(<meta (?:property="og:image"|name="twitter:image") content=")[^"]*(">)/g,
  `$1${versioned}$2`
);
if (after !== before) fs.writeFileSync(indexPath, after);

console.log(`wrote icons/og-image.jpg  ${W}x${H}  ${(fs.statSync(out).size / 1024).toFixed(0)} KB`);
console.log(`share-card URL is now  .../icons/og-image.jpg?v=${hash}`);
console.log(after !== before
  ? 'index.html updated — social platforms will refetch on their own, no debugger needed.'
  : 'index.html already carried this hash; the card is unchanged, nothing invalidated.');
console.log('\nRun `node tools/build-static-pages.mjs` so the county and grade pages pick it up,');
console.log('and bump CACHE_VERSION in sw.js.');
